    "89_1": {
      "title": "العشر فجرها لاح",
      "sabab": "",
      "fadl": "ما من أيام العمل الصالح أحب إلى الله فيهن من هذه الأيام (عشر ذي الحجة).",
      "action": "ضاعف الطاعات والاجتهاد في العبادة والصيام والذكر في العشر الأوائل من ذي الحجة."
    },
    "92_18": {
      "title": "الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّىٰ",
      "sabab": "عن عبد الله بن الزبير رضي الله عنهما قال: قال أبو قحافة لأبي بكر: أراك تعتق رقاباً ضعافاً، فلو أنك إذ فعلت، أعتقت رجالاً جلداً يمنعونك ويقومون دونك، فقال أبو بكر: يا أبت إني إنما أريد ما أريد، فنزلت هذه الآية فيه: { فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ ﴿٥﴾ وَصَدَّقَ بِٱلْحُسْنَىٰ ﴿٦﴾ فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ ﴿٧﴾ } إلى قوله عز و جل: { وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ ﴿١٩﴾ إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ ﴿٢٠﴾ } ولسوف يرضي.",
      "fadl": "",
      "action": ""
    },
    "93_1": {
      "title": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ وَالضُّحَىٰ",
      "sabab": "عن جُنْدُب بْنِ سُفْيَانَ رضي الله عنه قَالَ: اشْتَكَى رَسُولُ اللهِ ﷺ، فَلَمْ يَقُمْ لَيْلَتَيْنِ أَوْ ثَلاثاً، فَجَاءَتْ امْرَأَةٌ فَقَالَتْ: يَا مُحَمَّدُ، إِنِّي لَأَرْجُو أَنْ يَكُونَ شَيْطَانُكَ قَدْ تَرَكَكَ، لَمْ أَرَهُ قَرِبَكَ مُنْذُ لَيْلَتَيْنِ أَوْ ثَلَاثَةٍ، فَأَنْزَلَ اللهُ عز و جل: { وَٱلضُّحَىٰ ﴿١﴾ وَٱلَّيْلِ إِذَا سَجَىٰ ﴿٢﴾ مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ﴿٣﴾ }.",
      "fadl": "",
      "action": ""
    },
    "93_2": {
      "title": "وَاللَّيْلِ إِذَا سَجَىٰ",
      "sabab": "(تابع لسبب نزول الآية 1 من هذه السورة)",
      "fadl": "",
      "action": ""
    },
    "93_3": {
      "title": "ما ودعك ربك وما قلى",
      "sabab": "نزلت حين احتُبس الوحي عن النبي ﷺ فترة، فقال المشركون إن ربه ودّعه وقلاه، فنزلت هذه الآية تطمينًا للنبي ﷺ.",
      "fadl": "",
      "action": "في لحظات تأخر الفرج أو الشعور بالوحدة، تذكر أن الله ما ودّعك ولا تركك. هو معك دائمًا."
    },
    "93_5": {
      "title": "وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ",
      "sabab": "عن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ: « عرض علي ما هو مفتوح لأمتي بعدي ». فأنزل الله { وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ ﴿٤﴾ }.",
      "fadl": "",
      "action": ""
    },
    "94_5": {
      "title": "فإن مع العسر يسراً",
      "sabab": "نزلت تسليةً للنبي ﷺ وتذكيراً بأن مع كل شدة فرجاً.",
      "fadl": "كرّرها الله مرتين في سورة واحدة، فالعسر واحد باللام المعرّفة، واليسر اثنان بالتنكير، أي يُسران مقابل عسر واحد.",
      "action": "مع كل صعوبة تواجهها، اعلم أن معها يُسراً، وكلما اشتدّ الضيق، كلما اقترب الفرج."
    },
    "96_6": {
      "title": "كَلَّا إِنَّ الْإِنْسَانَ لَيَطْغَىٰ",
      "sabab": "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: قَالَ أَبُو جَهْلٍ: هَلْ يُعَفِّرُ مُحَمَّدٌ وَجْهَهُ بَيْنَ أَظْهُرِكُمْ، قَالَ: فَقِيلَ: نَعَمْ، فَقَالَ: وَاللَّاتِ وَالْعُزَّى لَئِنْ رَأَيْتُهُ يَفْعَلُ ذَلِكَ لأَطَأَنَّ عَلَى رَقَبَتِهِ، أَوْ لَأُعَفِّرَنَّ وَجْهَهُ فِي التُّرَابِ، قَالَ: فَأَتَى رَسُولَ اللهِ ﷺ وَهُوَ يُصَلِّيَ، زَعَمَ لِيَطَأَ عَلَى رَقَبَتِهِ، قَالَ: فَمَا فَجِئَهُمْ مِنْهُ إِلَّا وَهُوَ يَنْكُصُ عَلَى عَقِبَيْهِ، وَيَتَّقِي بِيَدَيْهِ، قَالَ: فَقِيلَ لَهُ: مَا لَكَ؟ فَقَالَ: إِنَّ بَيْنِي وَبَيْنَهُ لَخَنْدَقاً مِنْ نَارٍ وَهُوْلًا وَأَجْنِحَةً.\n\nفَقَالَ رَسُولُ اللهِ ﷺ: « لَوْ دَنَا مِنِّي لَاَخْتَطَفَتْهُ الْمَلَائِكَةُ عُضُوا عُضْوا ».\n\nقَالَ: فَأَنْزَلَ اللهُ عز و جل - لَا نَدْرِي فِي حَدِيثِ أَبِي هِرَيْرَةَ أَوْ شَيْءٌ بَلَغَهُ -: { كـَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ ﴿٦﴾ أَن رَّءَاهُ ٱسْتَغْنَىٰٓ ﴿٧﴾ إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ ﴿٨﴾ أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ ﴿٩﴾ عَبْدًا إِذَا صَلَّىٰٓ ﴿١٠﴾ أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ ﴿١١﴾ أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ ﴿١٢﴾ أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ ﴿١٣﴾ أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ ﴿١٤﴾ } يَعْنِي أَبَا جَهْلِ { كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعَۢا بِٱلنَّاصِيَةِ ﴿١٥﴾ نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ ﴿١٦﴾ فَلْيَدْعُ نَادِيَهُۥ ﴿١٧﴾ سَنَدْعُ ٱلزَّبَانِيَةَ ﴿١٨﴾ كَلَّا لَا تُطِعْهُ }، زَادَ عُبَيْدُ اللهِ فِي حَدِيثِهِ: قَالَ: وَأَمَرَهُ بِمَا أَمَرَهُ بِهِ.\n\nوَزَادَ ابْنُ عَبْدِ الْأَعْلَى: { فَلْيَدْعُ نَادِيَهُۥ } يَعْنِي قَوْمَهُ.\n\n📌 رواية أخرى: \nعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: كَانَ النَّبِيُّ ﷺ يُصَلِّي، فَجَاءَ أَبُو جَهْلٍ، فَقَالَ: أَلَمْ أَنْهَكَ عَنْ هَذَا؟ أَلَمْ أَنْهَكَ عَنْ هَذَا؟ أَلَمْ أَنْهَكَ عَنْ هَذَا؟ فَانْصَرَفَ النَّبِيُّ ﷺ فَزَبَرَهُ، فَقَالَ أَبُو جَهْلٍ: إِنَّكَ لَتَعْلَمُ مَا بِهَا نَادٍ أَكْثَرُ مِنِّي، فَأَنْزَلَ اللهُ { فَلْيَدْعُ نَادِيَهُۥ ﴿١٧﴾ سَنَدْعُ ٱلزَّبَانِيَةَ ﴿١٨﴾ }. فَقَالَ ابْنُ عَبَّاسٍ: فَوَاللهِ لَوْ دَعَا نَادِيَهُ لَأَخَذْتُهُ زَبَانِيَةُ اللهِ.",
      "fadl": "",
      "action": ""
    },
