    "97_1": {
      "title": "إنا أنزلناه في ليلة القدر",
      "sabab": "ذُكر للنبي ﷺ رجل من بني إسرائيل لبس السلاح مجاهداً وعابداً ألف شهر، فاستقلّ المسلمون أعمارهم وأعمالهم، فأنزل الله هذه السورة عطاءً لهذه الأمة.",
      "fadl": "العبادة فيها خير من عبادة 83 سنة متواصلة (ألف شهر).",
      "action": "أعمارنا قصيرة، لكن الله عوّضنا بمواسم تتضاعف فيها الأجور. استغل رمضان ومواسم الطاعات بذكاء."
    },
    "105_1": {
      "title": "ألم تر كيف فعل ربك بأصحاب الفيل",
      "sabab": "نزلت تذكيراً لأهل مكة بنعمة الله عليهم حين حماهم من جيش أبرهة الحبشي الذي جاء لهدم الكعبة بفيل ضخم ليصرف الحجاج لكنيسته.",
      "fadl": "",
      "action": "مهما بلغت قوة أعدائك أو حجم التحديات في حياتك، تذكر أن الله قادر على إهلاكهم بأضعف جنوده (طير أبابيل)."
    },
    "106_1": {
      "title": "لإيلاف قريش",
      "sabab": "امتن الله على قريش برحلتي الشتاء والصيف للتجارة، وحمايتهم في الحرم، ليدعوهم لعبادته وحده شكراً على الأمن والرزق.",
      "fadl": "",
      "action": "الأمان في بيتك ووجود الطعام على مائدتك نعمتان عظيمتان. لا تعتد النعمة، بل اشكر مُنعمها دوماً."
    },
    "108_1": {
      "title": "إنا أعطيناك الكوثر",
      "sabab": "مات أبناء النبي ﷺ الذكور، فقال أحد المشركين: دعوه فإنه أبتر (مقطوع النسل والذكر)، فأنزل الله السورة دفاعاً عنه وتبشيراً له بنهر الكوثر.",
      "fadl": "",
      "action": "من يدافع عن الله ورسوله يرفع الله ذكره ويخلده، ومن يعاديهم يُبتر ذكره وتنمحي سيرته. كن دائماً في صف الحق."
    },
