    "109_1": {
      "title": "قل يا أيها الكافرون",
      "sabab": "عرض كفار قريش على النبي ﷺ تسوية مضحكة: أن يعبد آلهتهم سنة، ويعبدون إلهه سنة! فنزلت السورة تقطع أي مساومة في العقيدة.",
      "fadl": "تعدل ربع القرآن، وقراءتها قبل النوم براءة من الشرك.",
      "action": "المبادئ لا تقبل المساومة ولا أنصاف الحلول. كن واضحاً وصريحاً في حقك ودينك ولا تتنازل إرضاءً للآخرين."
    },
    "111_1": {
      "title": "تبت يدا أبي لهب وتب",
      "sabab": "جمع النبي ﷺ قريشاً على جبل الصفا لدعوتهم، فقال له عمه أبو لهب: تباً لك سائر اليوم، ألهذا جمعتنا؟ فنزلت السورة رداً عليه وإبطالاً لكيده.",
      "fadl": "",
      "action": "القرابة والنسب لا تنفع بدون إيمان وعمل. أبو لهب عم النبي في النار، وبلال الحبشي في الجنة."
    },
