    "113_1": {
      "title": "قل أعوذ برب الفلق",
      "sabab": "سُحر النبي ﷺ من قِبَل يهودي يُدعى لبيد بن الأعصم، فأنزل الله المعوذتين رقيةً له، فكان كلما قرأ آية انحلت عقدة من السحر.",
      "fadl": "قال النبي ﷺ: «ألم تر آيات أُنزلت الليلة لم يُرَ مثلهن قط؟ قل أعوذ برب الفلق وقل أعوذ برب الناس».",
      "action": "حصن نفسك وأولادك يومياً بالمعوذتين، فهما أعظم وقاية من العين والحسد والسحر وشرور البشر."
    },
    "114_1": {
      "title": "قل أعوذ برب الناس",
      "sabab": "نزلت مع سورة الفلق حين سُحر النبي ﷺ ليسترقي بها ويتعوذ من شر شياطين الإنس والجن ووساوس الصدور.",
      "fadl": "من المعوذتين اللتين لا يستعاذ بمثلهما قط في دفع كل شر.",
      "action": "الشيطان يبدأ بالوسوسة الخفية في الصدر ليُحزنك أو يُفسد علاقتك بربك. اقطعه مباشرة بالتعوذ الصادق."
    }
